20	/// Same shape as `capture_flow_e2e_test.dart`'s/`entry_detail_flow_e2e_
21	/// test.dart`'s own fake adapter, extended with [queueSseResponse] for
22	/// `ApiClient.postStream`'s `ResponseType.stream` requests — only the
23	/// transport boundary is faked.
24	///
25	/// A queued SSE response is delivered as the exact [chunks] given, each
26	/// its own separate stream emission (never pre-joined into one string) —
27	/// this is what proves `ChatRemoteDataSource.sendMessage`'s own
28	/// `\n\n`-boundary buffering really works across genuine network chunk
29	/// boundaries, not just against a single already-complete event.
30	class _FakeHttpClientAdapter implements HttpClientAdapter {
31	  final List<RequestOptions> requests = [];
32	  final List<ResponseBody Function()> _queue = [];
33	
34	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
35	    _queue.add(
36	      () => ResponseBody.fromString(
37	        jsonEncode(body),
38	        statusCode,
39	        headers: {
40	          Headers.contentTypeHeader: [Headers.jsonContentType],
41	        },
42	      ),
43	    );
44	  }
45	
46	  void queueErrorResponse(String code, String message, {int statusCode = 503}) {
47	    queueJsonResponse(statusCode, {
48	      'code': code,
49	      'message': message,
50	      'retryable': true,
51	    });
52	  }
53	
54	  void queueSseResponse(List<String> chunks, {int statusCode = 200}) {
55	    _queue.add(
56	      () => ResponseBody(
57	        Stream.fromIterable(
58	          chunks.map((chunk) => Uint8List.fromList(utf8.encode(chunk))),
59	        ),
60	        statusCode,
61	        headers: {
62	          Headers.contentTypeHeader: ['text/event-stream'],
63	        },
64	      ),
65	    );
66	  }
67	
68	  @override
69	  Future<ResponseBody> fetch(
70	    RequestOptions options,
71	    Stream<Uint8List>? requestStream,
72	    Future<void>? cancelFuture,
73	  ) async {
74	    requests.add(options);
75	    if (_queue.isEmpty) {
76	      throw StateError(
77	        'No queued response for ${options.method} ${options.path}',
78	      );
79	    }
80	    return _queue.removeAt(0)();
81	  }
82	
83	  @override
84	  void close({bool force = false}) {}
85	}
86	
87	Map<String, dynamic> _sessionJson({required String id, required String updatedAt}) => {
88	  'id': id,
89	  'title': 'Nova conversa',
90	  'personaSnapshot': 'empatico',
91	  'userMessageCount': 0,
92	  'lastUserMessageAt': null,
93	  'createdAt': updatedAt,
94	  'updatedAt': updatedAt,
95	};
96	
97	/// `entries-create`'s own response `data` shape (`EntryDto.fromJson`) —
98	/// mirrors `entries_remote_data_source_test.dart`'s own fixture, extended
99	/// with a non-null [chatMessageId] (spec-6-4's own `source: chat` entries).
100	Map<String, dynamic> _entryJson({
101	  required String id,
102	  required String chatMessageId,
103	}) => {
104	  'id': id,
105	  'content': 'Como você está?',
106	  'source': 'chat',
107	  'chatMessageId': chatMessageId,
108	  'occurredAt': '2026-01-01T00:00:00Z',
109	  'serverRevision': 1,
110	  'createdAt': '2026-01-01T00:00:00Z',
111	  'updatedAt': '2026-01-01T00:00:00Z',
112	};
113	
114	/// End-to-end coverage for spec-6-1's chat flow, driven through the real
115	/// production object graph `sl` resolves for Home/Chat (the exact
116	/// `ChatCubit` instance `app_router.dart` gives `ChatScreen`), wired to
117	/// the real `ChatRepositoryImpl` -> `ChatRemoteDataSource` -> `ApiClient`
118	/// -> `Dio` (both real interceptors attached) -> the real `chat_sessions`/
119	/// `chat_messages` Hive boxes. Only the transport boundary and the native
120	/// plugins (secure storage, path_provider) are faked — no device/
121	/// simulator/CI exists yet (AGENTS.md).
122	///
123	/// Complements rather than duplicates this story's existing mocked tests
124	/// (`chat_cubit_test.dart` against a fake `ChatRepository`,
125	/// `chat_repository_impl_test.dart`/`chat_remote_data_source_test.dart`
126	/// against a mocked `ApiClient`): none of them drives a real SSE byte
127	/// stream through the real `ApiClient.postStream` -> `ChatRemoteDataSource`
128	/// `\n\n`-buffering -> `ChatCubit` token-append pipeline in one send, the
129	/// way the app actually does on every message.
130	///
131	/// Driven directly against `ChatCubit`'s own public API (`init`/
132	/// `sendMessage`), not through `tester.tap`/`pumpAndSettle` — same
133	/// rationale `capture_flow_e2e_test.dart` documents: these awaits span
134	/// genuine async I/O (a real Dio round trip over a faked transport), and
135	/// `pumpAndSettle` isn't guaranteed to wait for that.
136	void main() {
137	  TestWidgetsFlutterBinding.ensureInitialized();
138	
139	  const secureStorageChannel = MethodChannel(
140	    'plugins.it_nomads.com/flutter_secure_storage',
141	  );
142	  final fakeNativeStorage = <String, String>{};
143	
144	  // spec-6-3 — `sl<ChatCubit>()` below resolves the *real* `ChatCubit`,
145	  // whose constructor subscribes to the real `connectivity_plus`-backed
146	  // `ConnectivityWatcher` immediately; faked the same way
147	  // `bootstrap_integration_test.dart` fakes it, since no device/simulator
148	  // exists yet (AGENTS.md) to answer these channels for real.
149	  const connectivityMethodChannel = MethodChannel(
150	    'dev.fluttercommunity.plus/connectivity',
151	  );
152	  const connectivityEventChannel = EventChannel(
153	    'dev.fluttercommunity.plus/connectivity_status',
154	  );
155	
156	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
157	    final args = call.arguments as Map<dynamic, dynamic>;
158	    switch (call.method) {
159	      case 'write':
160	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
161	        return null;
162	      case 'read':
163	        return fakeNativeStorage[args['key'] as String];
164	      case 'delete':
165	        fakeNativeStorage.remove(args['key'] as String);
166	        return null;
167	      case 'containsKey':
168	        return fakeNativeStorage.containsKey(args['key'] as String);
169	      default:
170	        return null;
171	    }
172	  }
173	
174	  late FakePathProviderPlatform fakePathProvider;
175	  late _FakeHttpClientAdapter adapter;
176	
177	  // spec-6-3 — the real `connectivity_plus` plugin reaches this channel's
178	  // own event stream via `EventChannel.receiveBroadcastStream()`, not a
179	  // plain method call, so it must be mocked with `setMockStreamHandler`
180	  // rather than `setMockMethodCallHandler` to let a test push a live
181	  // reading. Captured on `onListen` (fired as soon as `sl<ChatCubit>()`'s
182	  // own constructor subscribes) so a test can call
183	  // `connectivityEventSink!.success([...])` to simulate a connectivity
184	  // change arriving from the OS.
185	  MockStreamHandlerEventSink? connectivityEventSink;
186	
187	  /// Pushes a live `connectivity_plus` reading and flushes the microtask
188	  /// hops between the fake event channel and `ChatCubit`'s own listener
189	  /// (the channel's `receiveBroadcastStream` -> `connectivity_plus`'s
190	  /// `distinct()` wrapper -> `ConnectivityPlusWatcher`'s own controller ->
191	  /// `ChatCubit._handleConnectivityChange`) — same `Future.delayed(Duration.
192	  /// zero)`-per-hop convention `connectivity_plus_watcher_test.dart` uses.
193	  Future<void> emitConnectivity(List<String> results) async {
194	    connectivityEventSink!.success(results);
195	    for (var i = 0; i < 5; i++) {
196	      await Future<void>.delayed(Duration.zero);
197	    }
198	  }
199	
200	  setUp(() async {
201	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
202	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
203	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
204	        .setMockMethodCallHandler(
205	          connectivityMethodChannel,
206	          (call) async => call.method == 'check' ? <String>['wifi'] : null,
207	        );
208	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
209	        .setMockStreamHandler(
210	          connectivityEventChannel,
211	          MockStreamHandler.inline(
212	            onListen: (_, events) => connectivityEventSink = events,
213	            onCancel: (_) => connectivityEventSink = null,
214	          ),
215	        );
216	    fakePathProvider = FakePathProviderPlatform();
217	    PathProviderPlatform.instance = fakePathProvider;
218	
219	    await resetCoreDependencies();
220	    await setupCoreDependencies();
221	
222	    adapter = _FakeHttpClientAdapter();
223	    sl<Dio>().httpClientAdapter = adapter;
224	
225	    // `chat-messages-send` et al. are bearer-required operations — seed a
226	    // user access token through the real `AccessTokenProvider` so the
227	    // real header interceptor has one to send.
228	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
229	  });
230	
231	  tearDown(() async {
232	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
233	        .setMockMethodCallHandler(secureStorageChannel, null);
234	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
235	        .setMockMethodCallHandler(connectivityMethodChannel, null);
236	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
237	        .setMockStreamHandler(connectivityEventChannel, null);
238	    fakeNativeStorage.clear();
239	    await Hive.close();
240	    await resetCoreDependencies();
241	    await fakePathProvider.cleanUp();
242	  });
243	
244	  test(
245	    'happy path: no existing session -> bootstrap creates one, then '
246	    'sendMessage() drives a genuine multi-chunk SSE POST to '
247	    'chat-messages-send/{sessionId} through the real pipeline, joining '
248	    'tokens split across chunk boundaries into one complete AI bubble',
249	    () async {
250	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
251	      adapter.queueJsonResponse(200, {
252	        'data': _sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z'),
253	      });
254	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
255	      adapter.queueSseResponse([
256	        'event: message_created\ndata: {"id":"srv-msg-1"}\n\n',
257	        // Split mid-event: this chunk ends inside an incomplete token
258	        // event's `data:` line, the next one finishes it and immediately
259	        // opens a second event in the same chunk.
260	        'event: token\ndata: {"delta":"Ol',
261	        'á, tudo bem?"}\n\nevent: token\ndata: {"delta":" Vamos conversar."}\n\n',
262	        'event: done\ndata: {}\n\n',
263	      ]);
264	
265	      final cubit = sl<ChatCubit>();
266	      await cubit.init();
267	      expect(cubit.state, isA<ChatReady>());
268	
269	      await cubit.sendMessage('Oi, bom dia!');
270	
271	      final state = cubit.state as ChatReady;
272	      expect(state.sessionId, 'session-1');
273	      expect(state.isSending, isFalse);
274	      expect(state.messages, hasLength(2));
275	      expect(state.messages[0].role, ChatMessageRole.user);
276	      expect(state.messages[0].content, 'Oi, bom dia!');
277	      expect(state.messages[0].status, ChatMessageStatus.complete);
278	      expect(state.messages[1].role, ChatMessageRole.assistant);
279	      expect(state.messages[1].content, 'Olá, tudo bem? Vamos conversar.');
280	      expect(state.messages[1].status, ChatMessageStatus.complete);
281	
282	      expect(adapter.requests, hasLength(4));
283	      final sendRequest = adapter.requests.last;
284	      expect(
285	        sendRequest.path,
286	        sl<UrlBuilder>().build('chat-messages-send', ['session-1']),
287	      );
288	      expect(sendRequest.data, {'content': 'Oi, bom dia!'});
289	      expect(sendRequest.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
290	      expect(
291	        sendRequest.headers['Authorization'],
292	        'Bearer e2e-test-access-token',
293	      );
294	
295	      // The real write-through happened against the real `chat_sessions`
296	      // Hive box (`createSession()`'s own persist-then-return step).
297	      final sessionsBox = sl<Box<Map>>(instanceName: 'chat_sessions');
298	      expect(sessionsBox.get('session-1'), isNotNull);
299	    },
300	  );
301	
302	  test(
303	    'review finding: a second sendMessage() on the same cubit, issued '
304	    'after the first one fully completed, resolves promptly through the '
305	    'real Dio/ApiClient.postStream subscription lifecycle — proves the '
306	    'stale-_sendSubscription-nulling fix (chat_cubit.dart\'s '
307	    '_consumeStream) actually works against a real subscription, not '
308	    'only the fake-StreamController-backed one unit tests use',
309	    () async {
310	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
311	      adapter.queueJsonResponse(200, {
312	        'data': _sessionJson(id: 'session-1', updatedAt: '2026-01-01T00:00:00Z'),
313	      });
314	      adapter.queueJsonResponse(200, {'data': <dynamic>[]});
315	      adapter.queueSseResponse([
316	        'event: token\ndata: {"delta":"Primeira resposta."}\n\n'
317	            'event: done\ndata: {}\n\n',
318	      ]);
319	      adapter.queueSseResponse([
320	        'event: token\ndata: {"delta":"Segunda resposta."}\n\n'
321	            'event: done\ndata: {}\n\n',
322	      ]);
323	
324	      final cubit = sl<ChatCubit>();
325	      await cubit.init();
326	
327	      await cubit.sendMessage('Primeira pergunta.');
328	      expect(
329	        (cubit.state as ChatReady).messages[1].content,
330	        'Primeira resposta.',
331	      );
332	
333	      // Without the fix, the first call's own now-finished subscription
334	      // is never cleared, so this second call's `await
